let promptEvent=null,registration=null,offlineReady=false,pwaError=false,mount=null,applyUpdate=false;
const installed=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const apple=()=>/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function draw(){let banner=document.getElementById("offlineStatus");if(!banner){banner=document.createElement("div");banner.id="offlineStatus";banner.className="pwa-state";banner.setAttribute("role","status");document.querySelector("header")?.after(banner);}banner.textContent=!navigator.onLine?(offlineReady?"离线模式 · 可查看、记录与导出":"当前离线 · 请先联网准备离线文件"):(offlineReady?"离线已就绪 · 断网也可训练":pwaError?"离线文件未准备好 · 请联网重试":"正在准备离线文件…");banner.hidden=true;window.dispatchEvent(new CustomEvent('training:pwa-status',{detail:banner.textContent}));if(!mount?.isConnected)return;mount.innerHTML=`<h3>添加到平板桌面</h3><p class="muted">${installed()?'已在独立应用窗口中打开。':'固定桌面入口，像应用一样直接打开训练卡。'}</p><div class="pwa-state">${!navigator.onLine?'当前离线 · 记录仍可在本机保存':offlineReady?'离线训练卡已就绪':pwaError?'离线准备未完成，请联网重新打开':'正在准备离线训练卡…'}</div>${!installed()?(promptEvent?'<button class="btn" id="installApp">安装训练卡</button>':`<div class="callout">${apple()?'用 Safari 打开当前网址 → 分享 → 添加到主屏幕 → 如有“作为网页 App 打开”，保持开启。':'在 Chrome／Edge 浏览器菜单中选择“安装应用”或“添加到主屏幕”；如仍在应用内浏览器，先用系统浏览器打开。'}</div>`):''}<p class="hint">首次联网显示离线就绪后可断网使用。手机和平板使用同一邮箱，联网自动同步；离线时显示最近同步的数据。</p>${registration?.waiting?'<button class="btn secondary" id="activateUpdate">新版已就绪，重新打开更新</button>':''}<button class="inline" id="checkPwaUpdate">检查应用更新</button><span class="tiny" id="updateMessage"></span>`;
const install=document.getElementById('installApp');if(install)install.onclick=async()=>{try{const p=promptEvent;await p.prompt();await p.userChoice;promptEvent=null;draw();}catch{promptEvent=null;draw();}};
const activate=document.getElementById('activateUpdate');if(activate)activate.onclick=()=>{if(document.querySelector('dialog[open]'))return;applyUpdate=true;registration.waiting?.postMessage({type:'ACTIVATE_UPDATE'});};
document.getElementById('checkPwaUpdate').onclick=async()=>{try{if(!navigator.onLine)throw Error('请联网后检查');if(!registration)throw Error('请使用系统浏览器联网重新打开');await registration.update();document.getElementById('updateMessage').textContent=registration.waiting?' 新版准备完成':' 已检查，当前可继续使用';}catch(e){document.getElementById('updateMessage').textContent=' '+e.message;}};
}
export function mountInstallCard(element){mount=element;draw();}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();promptEvent=event;draw();});window.addEventListener('appinstalled',()=>{promptEvent=null;draw();});window.addEventListener('online',draw);window.addEventListener('offline',draw);
if('serviceWorker'in navigator&&window.isSecureContext){let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(applyUpdate&&!refreshing){refreshing=true;location.reload();}else{offlineReady=true;draw();}});window.addEventListener('load',async()=>{try{registration=await navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'});offlineReady=!!registration.active;draw();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='activated'){offlineReady=true;draw();}if(worker.state==='installed')draw();if(worker.state==='redundant'){pwaError=true;draw();}});});await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Offline preparation timeout')),15000))]);offlineReady=true;draw();}catch{pwaError=true;draw();}});}else{pwaError=true;}
